#include "tools/sout"

#include <gtest/gtest.h>

namespace tools
{
//---------------------------------------------------------------------------//
TEST(Sout, BasicQuoting)
{
  EXPECT_EQ(sout("abc"), "\"abc\"");
}

TEST(Sout, EmptyString)
{
  EXPECT_EQ(sout(""), "\"\"");
}

TEST(Sout, StringWithQuotes)
{
  EXPECT_EQ(sout("a\"b\"c"), "\"a\"b\"c\"");
}

TEST(Sout, StringWithSpaces)
{
  EXPECT_EQ(sout(" a b c "), "\" a b c \"");
}

TEST(Sout, UnicodeString)
{
  // This is not compatible with C++20! See:
  // - https://stackoverflow.com/questions/56833000/c20-with-u8-char8-t-and-stdstring
  // - https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2019/p1423r2.html
  // sout s(u8"αβγ");
  // EXPECT_EQ(s, "\"αβγ\"");
  // Use byte sequences for now
  EXPECT_EQ(sout("\xCE\xB1\xCE\xB2\xCE\xB3"), "\"\xCE\xB1\xCE\xB2\xCE\xB3\"");
}

//---------------------------------------------------------------------------//
}  // namespace tools
